using System;
using System.IO;
using System.Linq;
using System.Collections;
using System.Collections.Generic;
using CatGunner.Runtime;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
public sealed class PlaytestIssuesRulesTests
{
 SaveData s;GunInventory guns;Missions missions;LocalPurchases store;DateTime now;
 [SetUp] public void Setup(){now=new DateTime(2026,10,11,12,0,0);s=new SaveData{Gun_Collect=new bool[65],Selected_items=new[]{0,-1,-1},Upgrade_Lv=new int[3]};guns=new GunInventory(s,(a,b)=>a);missions=new Missions(s,ProgressionCatalogue.Load(),guns,()=>now);missions.StartSeason();store=new LocalPurchases(s,guns,missions,()=>now);missions.PremiumAccess=()=>store.PremiumVerified;}
 [Test] public void AdPreviewKeepsNativeGateDailyLimitAndFullInventoryGuard(){Assert.That(guns.DrawDailyAd(now),Is.EqualTo(-1));Assert.That(guns.DrawDailyAd(now,true),Is.EqualTo(5));Assert.That(guns.DrawDailyAd(now,true),Is.EqualTo(-1));Assert.That(s.Dia,Is.Zero);Array.Fill(s.Owned_Gun_list,0);Assert.That(guns.DrawDailyAd(now.AddDays(1),true),Is.EqualTo(-1));Assert.That(s.AD_Daily_Gun_LastDate,Is.EqualTo("20261011"));}
 [Test] public void TrackAdvancesThroughFractionLevelCarryAndCap(){missions.AddExperience(25);Assert.That(missions.RewardSlotFill(0),Is.EqualTo(.25f));Assert.That(missions.RewardSlotFill(1),Is.Zero);missions.AddExperience(120);Assert.That(missions.RewardSlotFill(0),Is.EqualTo(1));Assert.That(missions.RewardSlotFill(1),Is.EqualTo(.45f));s.Mission_Reward_Lv=25;s.Mission_Reward_Exp=0;missions.AddExperience(300);Assert.That(s.Mission_Reward_Exp,Is.Zero);}
 [Test] public void NativeDiamondFirstBuyAndPackRewardsNeverCreateRealTransactions(){Assert.That(store.Apply("dia_0"),Is.True);Assert.That(s.Dia,Is.EqualTo(480));store.Apply("dia_0");Assert.That(s.Dia,Is.EqualTo(720));store.Apply("autoupgrade_pack");Assert.That(s.Dia,Is.EqualTo(1220));Assert.That(s.Is_AutoUpgrade_Pack,Is.True);Assert.That(store.Apply("autoupgrade_pack"),Is.False);Assert.That(s.PurchaseCount,Is.Zero);Assert.That(s.ProcessedTxnIds,Is.Empty);Assert.That(s.PurchaseHistory,Is.Empty);}
 [Test] public void SaveCodecRoundTripRetainsSimulationLedgerAndPremiumEligibility(){store.Apply("vip_pass");store.Apply("dia_0");var loaded=SaveArchive.Decode(SaveArchive.Encode(s));Assert.That(loaded.SimulatedPurchases.Count,Is.EqualTo(2));var inventory=new GunInventory(loaded,(a,b)=>a);var model=new Missions(loaded,ProgressionCatalogue.Load(),inventory,()=>now);var local=new LocalPurchases(loaded,inventory,model,()=>now);model.PremiumAccess=()=>local.PremiumVerified;Assert.That(model.VipAccess,Is.True);Assert.That(local.Recorded("dia_0"),Is.True);Assert.That(loaded.PurchaseHistory,Is.Empty);}
 [Test] public void CoreSpecialsUseRollingIntervalsRatherThanCalendarRollover(){store.Apply("catgunner_core_daily_750");now=now.Date.AddDays(1);Assert.That(store.CanBuy("catgunner_core_daily_750"),Is.False);now=now.AddHours(12);Assert.That(store.CanBuy("catgunner_core_daily_750"),Is.True);store.Apply("catgunner_core_weekly_1750");now=now.AddDays(6);Assert.That(store.CanBuy("catgunner_core_weekly_1750"),Is.False);now=now.AddDays(1);Assert.That(store.CanBuy("catgunner_core_weekly_1750"),Is.True);Assert.That(s.Adventure_Currency_Core[3],Is.EqualTo(2500));}
 [Test] public void WeeklyAndStepGunsRejectFullInventoryWithoutPartialRewards(){s.DailyGun_Purchase_Counts=new int[3];Array.Fill(s.Owned_Gun_list,0);Assert.That(store.Apply("catgunner_dailygun_0"),Is.False);Assert.That(store.Apply("catgunner_stepup_0"),Is.False);Assert.That(s.PetCoin,Is.Zero);Assert.That(s.SimulatedPurchases,Is.Empty);s.Owned_Gun_list[3]=-1;Assert.That(store.Apply("catgunner_dailygun_0"),Is.True);Assert.That(s.PetCoin,Is.EqualTo(300));Assert.That(s.DailyGun_Purchase_Counts[0],Is.EqualTo(1));Assert.That(store.Apply("catgunner_stepup_1"),Is.False);}
 [Test] public void LocalPremiumUnlocksEpicAndLuxuryXpAndExpiresAtSeasonReset(){Assert.That(missions.ClaimEpicReward(0),Is.False);Assert.That(store.Apply("vip_pass"),Is.True);Assert.That(s.Dia,Is.EqualTo(500));Assert.That(store.Apply("catgunner_luxury_upgrade"),Is.True);Assert.That(s.Mission_Reward_Lv,Is.EqualTo(3));Assert.That(missions.ClaimReward(0),Is.True);int dia=s.Dia;Assert.That(missions.ClaimEpicReward(0),Is.True);Assert.That(s.Dia-dia,Is.EqualTo(missions.Reward(0,true).value));int task=Array.FindIndex(missions.Catalogue.Missions,m=>!m.is_VIP_Mission&&m.type==0);s.Mission_TreeCount_Value=100000;Assert.That(missions.ClaimLuxuryMission(task),Is.False);Assert.That(missions.ClaimMission(task),Is.True);int exp=s.Mission_Reward_Lv*100+s.Mission_Reward_Exp;Assert.That(missions.ClaimLuxuryMission(task),Is.True);Assert.That(s.Mission_Reward_Lv*100+s.Mission_Reward_Exp-exp,Is.EqualTo((int)Math.Round(missions.Catalogue.Missions[task].ExpValue*.5,MidpointRounding.ToEven)));Assert.That(missions.ClaimLuxuryMission(task),Is.False);missions.ResetSeason(true);Assert.That(missions.VipAccess,Is.False);Assert.That(store.CanBuy("vip_pass"),Is.True);}
 [Test] public void PlusPackKeepsSevenDayExpiryAndPigKeepsNativeCapacityAndPurchaseLimit(){store.Apply("catgunner_pluspack_2");Assert.That(store.PlusActive(2),Is.True);Assert.That(store.Apply("catgunner_pluspack_2"),Is.False);now=now.AddDays(7);Assert.That(store.PlusActive(2),Is.False);s.Pig_Season_Index=RaidRules.SeasonIndex(now);s.Pig_Lv=1;s.Pig_Gem=659;Assert.That(store.Apply("stargem_pig_dynamic"),Is.False);s.Pig_Gem=660;Assert.That(store.Apply("stargem_pig_dynamic"),Is.True);Assert.That(s.StarGem,Is.EqualTo(660));Assert.That(s.Pig_Gem,Is.Zero);s.Pig_Gem=660;store.Apply("stargem_pig_dynamic");Assert.That(s.Pig_Lv,Is.EqualTo(2));}
}
public sealed class PlaytestIssuesRuntimeTests
{
 string folder;GameClient c;bool background;
 void Independent(Scene scene,LoadSceneMode mode){if(scene.name=="GameClient")scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<GameClient>(true)).Single().SaveFolderOverride=folder;}
 [UnitySetUp] public IEnumerator Setup(){background=Application.runInBackground;Application.runInBackground=true;Time.timeScale=1;folder=Path.Combine(Application.temporaryCachePath,"PlaytestIssues-"+Guid.NewGuid().ToString("N"));SceneManager.sceneLoaded+=Independent;yield return SceneManager.LoadSceneAsync("GameClient");yield return ClientStartupWait.Ready();c=GameClient.Instance;ForestRuntimeAcceptance.IsGaming=false;c.DailyLogin.Close();c.Tutorial.SetCleared();}
 [UnityTearDown] public IEnumerator Cleanup(){Time.timeScale=1;c?.LocalStore.Cancel();c?.RewardedAds.Cancel();yield return SceneManager.LoadSceneAsync("TargetPreview");SceneManager.sceneLoaded-=Independent;if(Directory.Exists(folder))Directory.Delete(folder,true);Application.runInBackground=background;}
 static IEnumerator Click(Button button){yield return new WaitForSeconds(.35f);Canvas.ForceUpdateCanvases();Assert.That(button.isActiveAndEnabled&&button.interactable,Is.True,button.name);var module=EventSystem.current.GetComponent<StandaloneInputModule>();var mouse=module.gameObject.AddComponent<ForestFeedbackMouseFixture>();module.inputOverride=mouse;try{var r=(RectTransform)button.transform;mouse.Position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center));var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(new PointerEventData(EventSystem.current){position=mouse.Position},hits);Assert.That(hits.Count,Is.GreaterThan(0));Assert.That(hits[0].gameObject.GetComponentInParent<Button>(),Is.SameAs(button),"Top hit: "+hits[0].gameObject.name);yield return null;mouse.Down=mouse.Held=true;yield return null;mouse.Down=mouse.Held=false;mouse.Up=true;yield return null;mouse.Up=false;yield return null;}finally{module.inputOverride=null;UnityEngine.Object.Destroy(mouse);}}
 void Capture(string name)=>ScreenCapture.CaptureScreenshot(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../reverse/com.Chodun.CatGunner/1.1.61-vc257/reports/visual/playtest-issues-"+name+"-gpu.png")));
 [UnityTest] public IEnumerator WeaponAdRealClickBeforeStage30GrantsOnceAndPersists(){Assert.That(c.State.Stage_Value_Max,Is.LessThan(30));for(var t=c.Guns.gunItemList.transform;t!=null;t=t.parent)t.gameObject.SetActive(true);yield return null;int before=c.State.Owned_Gun_list.Count(g=>g>=0);int dia=c.State.Dia;yield return Click(c.Guns.AD_Draw_Btn_obj.GetComponent<Button>());Assert.That(c.State.Owned_Gun_list.Count(g=>g>=0),Is.EqualTo(before+1));Assert.That(c.State.Owned_Gun_list.Any(g=>g>=5&&g<10),Is.True);Assert.That(c.State.Dia,Is.EqualTo(dia));Assert.That(c.RewardedAds.CompletedWatches,Is.EqualTo(1));c.Guns.AD_Draw_Btn_Click();yield return null;Assert.That(c.RewardedAds.CompletedWatches,Is.EqualTo(1));Assert.That(new SaveArchive(folder).Load().AD_Daily_Gun_LastDate,Is.EqualTo(DateTime.Now.ToString("yyyyMMdd")));Capture("weapon-ad");yield return null;}
 [UnityTest] public IEnumerator EquippingAllThreeCatsUsesSupportedBodyGunAndParticleMaterials(){for(int slot=1;slot<3;slot++){int index=c.Inventory.FirstEmpty;Assert.That(c.Inventory.AddRewardGun(10+slot),Is.True);Assert.That(c.Inventory.Equip(index,slot),Is.True);}yield return null;Assert.That(c.Team.Cat_list.All(cat=>cat.gameObject.activeInHierarchy),Is.True);foreach(var r in c.Team.Cat_list.SelectMany(cat=>cat.GetComponentsInChildren<Renderer>(true)))foreach(var m in r.sharedMaterials){Assert.That(m,Is.Not.Null,r.name);Assert.That(m.shader.isSupported&&m.shader.name!="Hidden/InternalErrorShader",Is.True,r.name+" "+m.shader.name);}Capture("three-cats");yield return null;}
 [UnityTest] public IEnumerator OriginalCashButtonSimulatesOnceAndRetainsRewardOnColdReload(){c.LocalStore.OpenShop();yield return null;var b=c.LocalStore.ShopUI.GetComponentsInChildren<LocalPurchaseButton>(true).Where(x=>x.ProductId=="autoupgrade_pack").OrderByDescending(x=>x.name=="Purchase_Btn").First();int dia=c.State.Dia;var scroll=b.GetComponentInParent<ScrollRect>();if(scroll!=null){Canvas.ForceUpdateCanvases();var viewport=scroll.viewport!=null?scroll.viewport:(RectTransform)scroll.transform;float range=scroll.content.rect.height-viewport.rect.height;if(range>0){float delta=viewport.rect.center.y-viewport.InverseTransformPoint(b.transform.position).y;scroll.verticalNormalizedPosition=Mathf.Clamp01(scroll.verticalNormalizedPosition-delta/range);}scroll.StopMovement();}yield return new WaitForSeconds(.4f);Capture("shop-offer");yield return null;yield return Click(b.Button);Assert.That(c.LocalStore.Completed,Is.EqualTo(1));Assert.That(c.State.Is_AutoUpgrade_Pack,Is.True);Assert.That(c.State.Dia,Is.EqualTo(dia+500));Assert.That(c.LocalStore.Request("autoupgrade_pack"),Is.False);Assert.That(c.State.PurchaseHistory,Is.Empty);Assert.That(c.State.ProcessedTxnIds,Is.Empty);Capture("purchase-success");yield return null;yield return SceneManager.LoadSceneAsync("GameClient");yield return ClientStartupWait.Ready();c=GameClient.Instance;ForestRuntimeAcceptance.IsGaming=false;c.DailyLogin.Close();Assert.That(c.State.Is_AutoUpgrade_Pack,Is.True);Assert.That(c.State.Dia,Is.EqualTo(dia+500));Assert.That(c.LocalStore.Model.Recorded("autoupgrade_pack"),Is.True,"Local simulation record must survive cold reload");Assert.That(c.LocalStore.Model.CanBuy("autoupgrade_pack"),Is.False);}
 [UnityTest] public IEnumerator CancellationDisabledSimulatorAndDuplicateRequestDoNotGrant(){int dia=c.State.Dia;Assert.That(c.LocalStore.Request("dia_0"),Is.True);Assert.That(c.LocalStore.Request("dia_0"),Is.False);c.LocalStore.Cancel();yield return null;Assert.That(c.State.Dia,Is.EqualTo(dia));c.OfflinePurchaseSimulation=false;Assert.That(c.LocalStore.Request("dia_0"),Is.False);c.OfflinePurchaseSimulation=true;Assert.That(c.LocalStore.Request("dia_0"),Is.True);yield return null;yield return null;Assert.That(c.LocalStore.Completed,Is.EqualTo(1));Assert.That(c.State.Dia,Is.EqualTo(dia+480));Assert.That(c.State.PurchaseCount,Is.Zero);}
 [UnityTest] public IEnumerator DailyMissionRealClaimMovesRewardTrackByXpFractionAndPersists(){c.MissionUI.NewSeason_Start();c.MissionUI.Panel_Open();yield return new WaitForSeconds(.4f);int index=Array.FindIndex(c.Missions.Catalogue.Missions,x=>!x.is_VIP_Mission&&x.type==0);c.State.Mission_TreeCount_Value=c.Missions.Catalogue.Missions[index].MissionValue;c.MissionUI.UI_Reload();yield return null;var row=c.MissionUI.Mission_Item_UI_List[index];var button=row.GetComponentsInChildren<Button>(true).Single(b=>Enumerable.Range(0,b.onClick.GetPersistentEventCount()).Any(i=>b.onClick.GetPersistentTarget(i)==row&&b.onClick.GetPersistentMethodName(i)=="Reward_Get"));yield return Click(button);int exp=c.Missions.Catalogue.Missions[index].ExpValue;Assert.That(c.State.Mission_Reward_Exp,Is.EqualTo(exp));Assert.That(c.MissionUI.Mission_Reward_Slot_List[0].Fill.fillAmount,Is.EqualTo(exp/100f));Assert.That(c.MissionUI.Mission_Reward_Slot_List[1].Fill.fillAmount,Is.Zero);Assert.That(new SaveArchive(folder).Load().Mission_Reward_Exp,Is.EqualTo(exp));Capture("mission-progress");yield return null;}
 [UnityTest] public IEnumerator PaidBuffAndMinePackApplyTheirLiveBenefitsAndKeepNativeAmounts(){var before=c.Hero.Damage.Value;float interval=c.Hero.AtkCool_Max;int dia=c.State.Dia;Assert.That(c.LocalStore.Request("buff_pack"),Is.True);yield return null;yield return null;Assert.That(c.Hero.Damage.Value.PlainInteger(),Is.EqualTo((before*new DecimalAmount(4)).PlainInteger()));Assert.That(c.Hero.AtkCool_Max,Is.EqualTo(Mathf.Clamp(interval/4,.05f,2)));Assert.That(c.LocalStore.Request("mine_pack"),Is.True);yield return null;yield return null;Assert.That(c.MineMode.Ticket_MaxCount_return(),Is.EqualTo(6));Assert.That(c.State.Dia,Is.EqualTo(dia+1500));var saved=new SaveArchive(folder).Load();Assert.That(saved.Is_Buff_Pack&&saved.Is_Mine_Pack,Is.True);}
 [UnityTest] public IEnumerator WeeklyGunPaymentUpdatesLiveCountersWalletAndArchive(){Assert.That(c.LocalStore.Request("catgunner_dailygun_0"),Is.True);yield return null;yield return null;Assert.That(c.State.PetCoin,Is.EqualTo(300));Assert.That(c.WeeklyGuns.Purchase_Counts[0],Is.EqualTo(1));Assert.That(c.Inventory.State.Owned_Gun_list.Contains(c.WeeklyGuns.GunNum_return(0)),Is.True);var saved=new SaveArchive(folder).Load();Assert.That(saved.DailyGun_Purchase_Counts[0],Is.EqualTo(1));Assert.That(saved.PetCoin,Is.EqualTo(300));Array.Fill(c.State.Owned_Gun_list,0);Assert.That(c.LocalStore.Request("catgunner_dailygun_0"),Is.False);Assert.That(c.State.DailyGun_Purchase_Counts[0],Is.EqualTo(1));}
}
